"use strict";
(function () {
  const indexUrl = "https://raw.githubusercontent.com/RSPSApp/tsps-plugins/main/catalogue.json";
  const releasesUrl = "https://github.com/RSPSApp/tsps-plugins/releases/download";
  const icons = {
    chat: ["M4 4h16v12H9l-5 4V4z", "M8 8h8M8 12h5"],
    grid: ["M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z"],
  };
  let catalogueRequest;
  function loadCatalogue() {
    if (!catalogueRequest) catalogueRequest = fetch(indexUrl).then(async response => {
      if (!response.ok) throw new Error("Catalogue unavailable");
      const index = await response.json();
      if (index?.format !== 1 || !Array.isArray(index.plugins)) throw new Error("Invalid catalogue");
      return index.plugins.map(plugin => {
        const {id, name, author, category, version, description} = plugin;
        if (typeof id !== "string" || !/^[a-z][a-z0-9-]{0,63}$/.test(id) ||
            typeof version !== "string" || !/^\d{1,6}\.\d{1,6}\.\d{1,6}$/.test(version) ||
            ![name, author, category, description].every(value => typeof value === "string" && value.trim())) {
          throw new Error("Invalid catalogue entry");
        }
        const download = `${releasesUrl}/${id}-v${version}/${id}-${version}.zip`;
        return {name, author, category, version, description, download};
      });
    }).catch(error => {
      catalogueRequest = undefined;
      throw error;
    });
    return catalogueRequest;
  }
  function node(tag, props = {}, children = []) {
    const element = document.createElement(tag);
    for (const [key, value] of Object.entries(props)) {
      if (key === "text") element.textContent = value;
      else if (key === "className") element.className = value;
      else if (key.startsWith("on")) element.addEventListener(key.slice(2), value);
      else element.setAttribute(key, String(value));
    }
    children.filter(child => child != null).forEach(child => element.append(typeof child === "string" ? document.createTextNode(child) : child));
    return element;
  }
  function icon(name) {
    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    for (const [key, value] of Object.entries({viewBox: "0 0 24 24", fill: "none", stroke: "currentColor", "stroke-width": "1.6", "stroke-linecap": "round", "stroke-linejoin": "round", class: "hub-icon", "aria-hidden": "true"})) svg.setAttribute(key, value);
    for (const d of icons[name] || icons.grid) {
      const path = document.createElementNS(svg.namespaceURI, "path");
      path.setAttribute("d", d);
      svg.append(path);
    }
    return svg;
  }
  function artwork(plugin) {
    return node("span", {className: "hub-plugin-icon"}, [icon(plugin.category === "Community" ? "chat" : "grid")]);
  }
  function tag(text, kind = "") { return node("span", {className: "hub-tag " + kind, text}); }
  let dialog;
  function showDetails(plugin) {
    if (!dialog) {
      dialog = node("dialog", {className: "hub-dialog hub-ui", "aria-labelledby": "hub-detail-title"});
      document.body.append(dialog);
    }
    dialog.replaceChildren();
    const heading = node("div", {className: "hub-card-title"}, [
      artwork(plugin),
      node("div", {}, [node("h2", {id: "hub-detail-title", text: plugin.name}), node("div", {className: "hub-author", text: "By " + plugin.author})]),
    ]);
    const body = node("div", {className: "hub-dialog-body"}, [
      heading, node("div", {className: "hub-dialog-meta"}, [tag(plugin.category), tag("TSPS release", "hub-tag-gold"), tag("v" + plugin.version)]),
      node("p", {text: plugin.description}),
    ]);
    const actions = node("div", {className: "hub-dialog-actions"}, [
      node("p", {text: "Import the ZIP from your server’s Plugins panel."}),
      node("button", {type: "button", text: "Close", onclick() { dialog.close(); }}),
      node("a", {className: "hub-button hub-primary", href: plugin.download, download: "", text: "Download ZIP"}),
    ]);
    dialog.append(body, actions);
    dialog.showModal();
  }
  function card(plugin) {
    const title = node("h3", {}, [node("button", {
      type: "button", className: "hub-text-button", text: plugin.name, onclick() { showDetails(plugin); },
    })]);
    const body = node("div", {className: "hub-card-body"}, [
      node("div", {className: "hub-card-title"}, [
        artwork(plugin),
        node("div", {}, [title, node("div", {className: "hub-author", text: "By " + plugin.author})]),
      ]),
      node("p", {className: "hub-card-description", text: plugin.description}),
      node("div", {className: "hub-card-meta"}, [tag(plugin.category)]),
      node("div", {className: "hub-card-actions"}, [
        node("span", {className: "hub-card-version", text: "v" + plugin.version}),
        node("a", {className: "hub-button", href: plugin.download, download: "", text: "Download ZIP", "aria-label": "Download " + plugin.name + " ZIP"}),
      ]),
    ]);
    return node("article", {className: "hub-card"}, [body]);
  }
  function renderCatalogue(container, options, catalogue) {
    const categories = ["All plugins", ...new Set(catalogue.map(plugin => plugin.category))];
    let category = "All plugins";
    const search = options.searchInput || node("input", {type: "search", placeholder: "Search plugins, features or authors", "aria-label": "Search Plugin Hub"});
    const grid = node("div", {className: "hub-catalogue"});
    const resultCount = node("span", {className: "hub-result-count", role: "status"});
    const filters = node("div", {className: "hub-filter-chips", "aria-label": "Filter plugins"});
    const empty = node("div", {className: "hub-empty"}, [node("strong", {text: "No plugins found"}), "Try another search or category."]);
    function chooseCategory(next) { category = next; render(); }
    function render() {
      const words = search.value.trim().toLowerCase().split(/\s+/).filter(Boolean);
      const matches = catalogue.filter(p => (category === "All plugins" || p.category === category)
        && words.every(word => [p.name, p.author, p.category, p.description].join(" ").toLowerCase().includes(word)));
      resultCount.textContent = matches.length + (matches.length === 1 ? " plugin" : " plugins");
      grid.replaceChildren(...matches.map(card));
      empty.hidden = matches.length > 0;
      for (const button of filters.children) button.setAttribute("aria-pressed", String(button.dataset.category === category));
    }
    for (const name of categories) {
      filters.append(node("button", {type: "button", "data-category": name, text: name, "aria-pressed": String(name === category), onclick() { chooseCategory(name); }}));
    }
    container.replaceChildren(
      ...(options.searchInput ? [] : [node("div", {className: "hub-search-row"}, [search])]),
      filters,
      node("div", {className: "hub-heading"}, [node("h2", {text: "Explore plugins"}), resultCount]), grid, empty);
    search.addEventListener("input", render);
    render();
    return {refresh: render, destroy() {
      search.removeEventListener("input", render);
    }};
  }
  function mountBrowse(container, options = {}) {
    container.classList.add("hub-ui");
    let destroyed = false;
    let view;
    function load() {
      container.replaceChildren(node("p", {role: "status", text: "Loading plugins…"}));
      loadCatalogue().then(catalogue => {
        if (!destroyed) view = renderCatalogue(container, options, catalogue);
      }, () => {
        if (!destroyed) container.replaceChildren(
          node("p", {role: "status", text: "Could not load the Plugin Hub catalogue."}),
          node("button", {type: "button", text: "Retry", onclick: load}),
        );
      });
    }
    load();
    return {refresh: () => view?.refresh(), destroy() {
      destroyed = true;
      view?.destroy();
    }};
  }
  window.PluginHub = {mountBrowse};
})();

"use strict";
window.LocalPlayers = {
  mount(container, el, api, flash) {
    const rightsLabels = LocalPanelComponents.rightsLabels;
    const skillNames = ["Attack", "Defence", "Strength", "Hitpoints", "Ranged", "Prayer", "Magic", "Cooking", "Woodcutting",
      "Fletching", "Fishing", "Firemaking", "Crafting", "Smithing", "Mining", "Herblore", "Agility", "Thieving",
      "Slayer", "Farming", "Runecrafting", "Construction", "Hunter"];
    const skillOrder = [0, 2, 1, 4, 5, 6, 20, 21, 3, 16, 15, 17, 12, 9, 18, 22, 14, 13, 10, 7, 11, 8, 19];
    let players = [];
    let selected;
    let detail;
    let view = "preview";
    let sort = "rights";
    let descending = true;
    let running = false;
    let refreshId = 0;
    let skillIcons = [];
    const search = el("input", { type: "search", placeholder: "Search players", "aria-label": "Search players", oninput: renderList });
    const list = el("div");
    const table = LocalPanelComponents.playersTable(list);
    const pane = el("div", { className: "local-player-pane", hidden: true });
    container.append(el("div", { className: "local-players" }, [
      el("div", { className: "local-player-pane" }, [
        el("div", { className: "local-player-heading" }, [
          search, el("button", { type: "button", text: "Refresh", onclick: refresh }),
        ]),
        list,
      ]), pane,
    ]));
    void api("/panel/skill-icons.json").then(result => {
      if (result.ok) {
        skillIcons = result.body.skills;
        renderDetail();
      }
    }).catch(() => {});

    async function request(path, body) {
      const result = await api(path, body);
      if (!result.ok) throw new Error(result.body?.error || "Could not reach the server.");
      return result.body;
    }

    function renderList() {
      table.render({ players, query: search.value, sort: { key: sort, desc: descending }, selected,
        rightsDisabled: !running,
        onSort(column) {
          descending = sort === column ? !descending : column !== "username";
          sort = column;
          renderList();
        },
        onSelect: player => void choose(player.id),
        onRights: (player, rights) => void change(player.id, "rights", { rights }),
      });
    }

    function renderDetail() {
      pane.hidden = !selected;
      if (pane.hidden) {
        pane.replaceChildren();
        return;
      }
      const player = detail?.player;
      if (!player) {
        pane.replaceChildren(el("p", { className: "local-player-empty", text: "Loading player…" }));
        return;
      }
      const actions = el("details", { className: "local-player-actions" }, [
        el("summary", { text: "Actions" }),
        el("div", null, [
          el("button", { type: "button", text: "Kick", disabled: !running || !player.online, onclick: () => change(player.id, "kick") }),
          el("button", { type: "button", text: player.banned ? "Unban" : "Ban", disabled: !running, onclick: () => change(player.id, "ban", { enabled: !player.banned }) }),
          el("button", { type: "button", text: player.muted ? "Unmute" : "Mute", disabled: !running, onclick: () => change(player.id, "mute", { enabled: !player.muted }) }),
        ]),
      ]);
      const views = el("div", { className: "local-player-view", role: "group", "aria-label": "Player view" },
        ["preview", "json"].map(name => el("button", {
          type: "button", text: name === "json" ? "JSON" : "Preview", "aria-pressed": String(view === name),
          onclick() { view = name; renderDetail(); },
        })));
      const save = detail.save;
      const summary = [
        ["Rights", rightsLabels[player.rights]], ["Combat level", player.combat], ["Total level", player.total],
        ["Kills / deaths", (save.totalKills ?? 0) + " / " + (save.deaths ?? 0)],
        ["Best killstreak", save.highestKillstreak ?? 0], ["Status", player.online ? "Online" : "Offline"],
      ].map(([label, value]) => el("div", null, [el("dt", { text: label }), el("dd", { text: String(value ?? "—") })]));
      const levels = save.skills?.maxLevel;
      const skills = Array.isArray(levels) ? el("div", { className: "local-player-skills", "aria-label": "Skills" },
        skillOrder.filter(index => Number.isFinite(levels[index])).map(index => el("div", {
          className: "local-skill-tile", title: skillNames[index],
        }, [
          skillIcons[index] ? el("img", { src: skillIcons[index], alt: skillNames[index] }) : skillNames[index],
          el("strong", { text: String(levels[index]) }),
        ]))) : null;
      pane.replaceChildren(
        el("div", { className: "local-player-heading" }, [el("strong", { text: player.username }), actions, views]),
        el("div", { className: "local-player-detail" }, [
          view === "json" ? el("pre", { text: JSON.stringify(save, null, 2) }) : el("dl", null, summary),
          view === "preview" ? skills : null,
        ]),
      );
    }

    async function choose(id) {
      selected = id;
      detail = null;
      renderList();
      renderDetail();
      try {
        const result = await request("/api/players/save?name=" + encodeURIComponent(id));
        if (selected === id) { detail = result; renderDetail(); }
      } catch (error) {
        if (selected !== id) return;
        selected = null;
        renderDetail();
        flash("error", error.message);
      }
    }

    async function refresh() {
      const id = ++refreshId;
      try {
        const result = await request("/api/players");
        if (id !== refreshId) return;
        players = result.players;
        if (selected && players.some(player => player.id === selected)) await choose(selected);
        else { selected = null; detail = null; renderList(); renderDetail(); }
      } catch (error) {
        if (id === refreshId) table.error(error.message);
      }
    }

    async function change(id, action, options) {
      try {
        await request("/api/players/action?name=" + encodeURIComponent(id), { action, ...options });
        await refresh();
      } catch (error) {
        renderList();
        flash("error", error.message);
      }
    }

    renderDetail();
    return { refresh, setOnline(online) {
      if (running === online) return;
      running = online;
      renderList();
      renderDetail();
    } };
  },
};
